# parse sections labels; helper

def parse_after_label(text, label, stoplabel=None):
    start=text.index(label)
    tail=text[start:].splitlines()[1:]
    rows=[]
    for line in tail:
        if not line or not re.match(r'^\d',line): break
        vals=[int(x) for x in line.split()]
        if vals: rows.append(vals)
    return np.array(rows,dtype=int)
